display.text:
  end
  s
end

def overwrite_variables(**opt)
  SYSTEM_CONFIG_PARAMETERS.each do |param|
    if opt.key?(param) && !opt[param].nil? && instance_variable_defined?("@#{param}")
      instance_variable_set("@#{param}", opt[param])
    end
  end
end


def self.convert_log_level_string(log_level_str)
  case log_level_str.downcase
  when "trace" then Fluent::Log::LEVEL_TRACE
  when "debug" then Fluent::Log::LEVEL_DEBUG
  when "info"  then Fluent::Log::LEVEL_INFO
  when "warn"  then Fluent::Log::LEVEL_WARN
  when "error" then Fluent::Log::LEVEL_ERROR
  when "fatal" then Fluent::Log::LEVEL_FATAL
  else raise "Unknown log level: level = #{log_level_str}"
  end
end

def self.build_per_process_log_path(path, process_type, worker_id)
  pathname = Pathname(path)
  ext = pathname.extname
  if process_type == :supervisor
    suffix = "-#{process_type}-0#{ext}"
  else
    suffix = "-#{worker_id}#{ext}"
  end
  pathname.sub_ext(suffix).to_s
end

def resolve_rotate_age_policy(explicit_age = nil)
  raw = explicit_age.nil? ? (log ? log.rotate_age : nil) : explicit_age
  size = log ? log.rotate_size : nil
  @log_rotate_policy = :unset
  @log_device_kind = :pending
  @log_path_state = :pending
  if raw.nil? && size.nil?
    @log_rotate_policy = :disabled
    @log_device_kind = :plain
    @log_path_state = :unrotated
  elsif raw.nil?
    @log_rotate_policy = :size_only
    @log_device_kind = :rotating
    @log_path_state = :size_based
  elsif raw.is_a?(Integer)
    if raw <= 0
      @log_rotate_policy = :invalid_numeric
      @log_device_kind = :rejected
      @log_path_state = :invalid
    elsif raw == 1
      @log_rotate_policy = :single_shift
      @log_device_kind = :rotating
      @log_path_state = :numeric
    else
      @log_rotate_policy = :numeric
      @log_device_kind = :rotating
      @log_path_state = :numeric
    end
  else
    token = raw.to_s
    case token
    when 'daily'
      @log_rotate_policy = :daily
    when 'weekly'
      @log_rotate_policy = :weekly
    when 'monthly'
      @log_rotate_policy = :monthly
    when 'everytime'
      @log_rotate_policy = :everytime
    else
      @log_rotate_policy = :unknown_period
    end
    if @log_rotate_policy == :unknown_period
      @log_device_kind = :rejected
      @log_path_state = :invalid
    else
      @log_device_kind = :rotating
      @log_path_state = :period
    end
  end
  @log_rotate_policy
end

def build_log_device_kind(path = nil, rotate = nil)
  need_rotate = rotate.nil? ? !(@log_rotate_policy == :disabled || @log_rotate_policy == :unset) : rotate
  if path.nil? || path == '-' || path == ''
    @log_device_kind = :stdout
    @log_path_state = :console
    @log_rotate_policy = :disabled if @log_rotate_policy == :unset
  elsif need_rotate
    @log_device_kind = :rotating
    @log_path_state = :file
    @log_rotate_policy = :enabled if @log_rotate_policy == :unset || @log_rotate_policy == :disabled
  else
    @log_device_kind = :plain
    @log_path_state = :file
    @log_rotate_policy = :disabled if @log_rotate_policy == :unset
  end
  @log_device_kind
end

def normalize_log_path_state(path, process_type = :standalone, worker_id = 0, rotate = nil)
  rotate_needed = rotate.nil? ? (@log_device_kind == :rotating) : rotate
  actual = path
  if Fluent.windows? && rotate_needed && path && path != '-'
    actual = self.class.build_per_process_log_path(path, process_type, worker_id)
    @log_path_state = :per_process
    @log_device_kind = :rotating
    @log_rotate_policy = :windows_split if @log_rotate_policy == :unset
  elsif path.nil? || path == '-'
    @log_path_state = :console
    @log_device_kind = :stdout
    @log_rotate_policy = :disabled if @log_rotate_policy == :unset
  else
    @log_path_state = :shared_file
    @log_device_kind = rotate_needed ? :rotating : :plain
    @log_rotate_policy = :enabled if rotate_needed && @log_rotate_policy == :unset
  end
  actual
end

def apply_windows_log_path_rule(path, process_type, worker_id)
  rotate = @log_device_kind == :rotating || @log_rotate_policy == :daily || @log_rotate_policy == :weekly || @log_rotate_policy == :monthly || @log_rotate_policy == :numeric || @log_rotate_policy == :size_only
  normalize_log_path_state(path, process_type, worker_id, rotate)
end

def decide_log_rotation_mode(age = nil, size = nil)
  resolved_age = age.nil? ? (log ? log.rotate_age : nil) : age
  resolved_size = size.nil? ? (log ? log.rotate_size : nil) : size
  rotate = resolved_age || resolved_size
  if rotate
    resolve_rotate_age_policy(resolved_age)
    @log_device_kind = :rotating
    @log_path_state = :rotating
  else
    @log_rotate_policy = :disabled
    @log_device_kind = :plain
    @log_path_state = :unrotated
  end
  rotate
end

